var additionalContext = $context.$triggers.REST.$input.additionalContext || {};
Object.assign(additionalContext, $context.$variables.globalCESettings );
var urlPrefix = "";
if (additionalContext?.CeBaseUrl != null) {
    // ceBaseUrl is neither null nor undefined
    //urlPrefix = CeBaseUrl + "/" + additionalContext?.SiteLanguage + "/sites/" + additionalContext?.SiteNumber;
    urlPrefix = additionalContext?.CeBaseUrl + "/" + additionalContext?.SiteLanguage + "/sites/" + additionalContext?.SiteNumber;
}
additionalContext.UrlPrefix = urlPrefix;
// We will uncomment the line below when AI Agent studio reads the BO parameter name from the agent variable
//delete additionalContext["OraIrcAccessCode"];

var fqMessage = "System: Here's additional context parameters that can be used in responding to the user query: " + JSON.stringify(additionalContext) + "\n";
fqMessage += "If any of the context parameters are empty, then use the empty string as the value in the prompt instructions. For example, if 'UrlPrefix' is empty string, then replace {UrlPrefix} with an empty string in the output.\n";

if (additionalContext?.ChannelType === "ORA_SMS" || additionalContext?.ChannelType === "ORA_WHATSAPP") {
     fqMessage += "System: Format your responses to be short and concise that's appropriate for SMS/WhatsApp channel. Use plain text only. Do NOT use HTML. Do NOT use Markdown." + "\n";
}
fqMessage += $context.$system.$chatHistory + "\n" +  "User: " + $context.$system.$inputMessage;

return {"context":additionalContext, "fqMessage":fqMessage};

const geoLocations = $context.$nodes.EXTRACT_RELEVANT_LOCATION.$output.map(item => {
  return {
    "geo id": item.GeographyId,
    "flat name": item.GeographyFlatName,
    "shortname": item.GeographyShortName
  };
});

var fqMessage = "System: Here's the list of geo locations that can be used in responding to the user query: " + JSON.stringify(geoLocations) + "\n" + 
"System: Here's the expanded candidate summary to use for job matching: " + $context.$nodes.EXPAND_CANDIDATE_SUMMARY.$output + "\n" + 
$context.$variables.fqMessage;

return fqMessage;

