// 1. Define the specific keys you want to extract
const keysToExtract = [
  "ORA_IRC_TC_OPTIN_ENABLED"
];

// 2. Extract and populate the new object
const extractedSettings = $context.$nodes.GET_GLOBAL_SETTINGS.$output.settings.reduce((acc, item) => {
  if (keysToExtract.includes(item.settingKey)) {
    acc[item.settingKey] = item.settingValue;
  }
  return acc;
}, {});

return extractedSettings;
